package com.webox;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.context.properties.ConfigurationPropertiesScan;
import org.springframework.scheduling.annotation.EnableScheduling;

@SpringBootApplication
@EnableScheduling
@ConfigurationPropertiesScan
public class WeboxApplication {
    public static void main(String[] args) {
        SpringApplication.run(WeboxApplication.class, args);
    }
}

package com.webox.common;

import org.springframework.http.HttpStatus;

/** Business failure carrying an English, user-presentable message plus a machine-readable code. */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;
    private final Object details;

    public ApiException(HttpStatus status, String code, String message) {
        this(status, code, message, null);
    }

    public ApiException(HttpStatus status, String code, String message, Object details) {
        super(message);
        this.status = status;
        this.code = code;
        this.details = details;
    }

    public static ApiException badRequest(String code, String message, Object details) {
        return new ApiException(HttpStatus.BAD_REQUEST, code, message, details);
    }

    public static ApiException conflict(String code, String message) {
        return new ApiException(HttpStatus.CONFLICT, code, message);
    }

    public static ApiException conflict(String code, String message, Object details) {
        return new ApiException(HttpStatus.CONFLICT, code, message, details);
    }

    public static ApiException notFound(String code, String message) {
        return new ApiException(HttpStatus.NOT_FOUND, code, message);
    }

    public static ApiException forbidden(String code, String message) {
        return new ApiException(HttpStatus.FORBIDDEN, code, message);
    }

    public static ApiException unauthorized(String code, String message) {
        return new ApiException(HttpStatus.UNAUTHORIZED, code, message);
    }

    public HttpStatus status() {
        return status;
    }

    public String code() {
        return code;
    }

    public Object details() {
        return details;
    }
}

package com.webox.common;

import com.fasterxml.jackson.annotation.JsonInclude;
import java.util.List;
import java.util.Map;

/** Uniform error envelope: {code, message, fieldErrors?, details?}. */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record ErrorResponse(String code, String message, Map<String, String> fieldErrors, Object details) {

    public static ErrorResponse of(String code, String message) {
        return new ErrorResponse(code, message, null, null);
    }

    public static ErrorResponse fields(String code, String message, Map<String, String> fieldErrors) {
        return new ErrorResponse(code, message, fieldErrors, null);
    }

    public static ErrorResponse field(String code, String message, String field, String fieldMessage) {
        return new ErrorResponse(code, message, Map.of(field, fieldMessage), null);
    }

    public static ErrorResponse withDetails(String code, String message, Object details) {
        return new ErrorResponse(code, message, null, details);
    }

    public record StockShortage(long menuId, String dishName, int requested, int remaining) {}

    public record ActiveOrderRef(long orderId, String orderNo, String status) {}

    public record InvalidOption(long menuId, String groupName, String message) {}

    public record ListDetails(List<StockShortage> items) {}
}

package com.webox.common;

import jakarta.servlet.http.HttpServletRequest;
import java.time.format.DateTimeParseException;
import java.util.LinkedHashMap;
import java.util.Map;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.MissingRequestHeaderException;
import org.springframework.web.bind.MissingServletRequestParameterException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
import org.springframework.web.servlet.NoHandlerFoundException;

@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<ErrorResponse> handleApi(ApiException ex) {
        return ResponseEntity.status(ex.status())
                .body(new ErrorResponse(ex.code(), ex.getMessage(), null, ex.details()));
    }

    /** Bean-validation failures are reported per field so the SPA can render inline messages. */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ErrorResponse> handleValidation(MethodArgumentNotValidException ex) {
        Map<String, String> fields = new LinkedHashMap<>();
        ex.getBindingResult().getFieldErrors()
                .forEach(fe -> fields.putIfAbsent(fe.getField(), fe.getDefaultMessage()));
        ex.getBindingResult().getGlobalErrors()
                .forEach(ge -> fields.putIfAbsent("_global", ge.getDefaultMessage()));
        return ResponseEntity.badRequest()
                .body(ErrorResponse.fields("VALIDATION_ERROR", "Please check the highlighted fields.", fields));
    }

    @ExceptionHandler({MissingServletRequestParameterException.class, MissingRequestHeaderException.class,
            MethodArgumentTypeMismatchException.class, HttpMessageNotReadableException.class,
            DateTimeParseException.class, IllegalArgumentException.class})
    public ResponseEntity<ErrorResponse> handleMalformed(Exception ex) {
        log.debug("Malformed request: {}", ex.getMessage());
        return ResponseEntity.badRequest()
                .body(ErrorResponse.of("MALFORMED_REQUEST", "The request could not be processed. Please check the submitted values."));
    }

    @ExceptionHandler(DataIntegrityViolationException.class)
    public ResponseEntity<ErrorResponse> handleIntegrity(DataIntegrityViolationException ex) {
        log.warn("Data integrity violation: {}", ex.getMostSpecificCause().getMessage());
        return ResponseEntity.status(HttpStatus.CONFLICT)
                .body(ErrorResponse.of("CONFLICT", "That change conflicts with existing data."));
    }

    @ExceptionHandler(NoHandlerFoundException.class)
    public ResponseEntity<ErrorResponse> handleNoHandler(NoHandlerFoundException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
                .body(ErrorResponse.of("NOT_FOUND", "Resource not found."));
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleUnexpected(HttpServletRequest request, Exception ex) {
        log.error("Unhandled error on {} {}", request.getMethod(), request.getRequestURI(), ex);
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(ErrorResponse.of("INTERNAL_ERROR", "Something went wrong on our side. Please try again."));
    }
}

package com.webox.domain;

/** Fixed vocabularies shared by the menu, preferences and the Console. Kept as enums so the
 *  database, the API and the UI cannot drift apart. */
public final class Enums {

    private Enums() {}

    public enum Role { EMPLOYEE, ADMIN }

    public enum Category { Chinese, Western, Japanese, Korean, Light_Meal, Southeast_Asian;
        /** Enum name uses underscores (Java identifiers); the wire/DB value uses spaces. */
        public String value() { return name().replace('_', ' '); }
        public static Category fromValue(String v) {
            if (v == null) return null;
            String n = v.trim().replace(' ', '_');
            for (Category c : values()) if (c.name().equalsIgnoreCase(n)) return c;
            return null;
        }
    }

    public enum SpiceLevel { None, Mild, Medium, Hot }

    public enum Allergen { Peanuts, Dairy, Egg, Gluten, Soy, Fish, Shellfish }

    public enum Taste { Light, Balanced, Rich }

    public enum MealPeriod { LUNCH, DINNER }

    public enum OrderStatus { Pending, Confirmed, Completed, Cancelled;
        public boolean isActive() { return this == Pending || this == Confirmed; }
    }
}

package com.webox.common;

import java.math.BigDecimal;
import java.math.RoundingMode;

/** All money crossing the API is an integer number of cents; storage is DECIMAL(10,2).
 *  Nothing in the system ever holds a monetary value in a double. */
public final class Money {

    public static final BigDecimal HUNDRED = BigDecimal.valueOf(100);
    public static final int MAX_CENTS = 100_000; // ¥1,000.00 upper bound for a single price field

    private Money() {}

    public static long toCents(BigDecimal amount) {
        if (amount == null) return 0L;
        return amount.movePointRight(2).setScale(0, RoundingMode.HALF_UP).longValueExact();
    }

    public static BigDecimal fromCents(long cents) {
        return BigDecimal.valueOf(cents).movePointLeft(2).setScale(2, RoundingMode.UNNECESSARY);
    }

    public static BigDecimal normalize(BigDecimal amount) {
        return amount == null ? BigDecimal.ZERO.setScale(2) : amount.setScale(2, RoundingMode.HALF_UP);
    }
}

package com.webox.common;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.List;
import java.util.Map;

/** Small JSON helpers for the denormalised columns (allergens, cuisine preferences, item options). */
public final class Json {

    private static final ObjectMapper MAPPER = new ObjectMapper();
    private static final TypeReference<List<String>> STRING_LIST = new TypeReference<>() {};

    private Json() {}

    public static List<String> toList(String csv) {
        if (csv == null || csv.isBlank()) return List.of();
        return List.of(csv.split(",")).stream().map(String::trim).filter(s -> !s.isEmpty()).toList();
    }

    public static String toCsv(List<String> values) {
        if (values == null || values.isEmpty()) return "";
        return String.join(",", values.stream().map(String::trim).filter(s -> !s.isEmpty()).distinct().toList());
    }

    public static String write(Object value) {
        try {
            return MAPPER.writeValueAsString(value);
        } catch (Exception e) {
            throw new IllegalStateException("Unable to serialise value", e);
        }
    }

    public static List<Map<String, Object>> readMapList(String json) {
        if (json == null || json.isBlank()) return List.of();
        try {
            return MAPPER.readValue(json, new TypeReference<List<Map<String, Object>>>() {});
        } catch (Exception e) {
            return List.of();
        }
    }

    public static List<String> readStringList(String json) {
        if (json == null || json.isBlank()) return List.of();
        try {
            return MAPPER.readValue(json, STRING_LIST);
        } catch (Exception e) {
            return List.of();
        }
    }
}

